package erratum

import (
	"errors"
	"fmt"
)

// Use opens a resource via the provided opener, calls Frob(input) on it, and
// guarantees the resource is closed exactly once, even when an error or panic
// occurs.
//
// If the opener returns a TransientError, Use keeps retrying the open. Any
// other error from the opener is returned from Use. If Frob panics with a
// FrobError, the resource's Defrob is called with the error's defrobTag before
// the resource is closed. In all cases the recovered error (or nil on success)
// is returned.
func Use(opener ResourceOpener, input string) (err error) {
	var resource Resource
	for {
		resource, err = opener()
		if err == nil {
			break
		}
		var transient TransientError
		if errors.As(err, &transient) {
			// The resource is temporarily unavailable; retry the open.
			continue
		}
		return err
	}

	// Ensure the resource is closed exactly once, no matter what happens.
	// This is registered before the recover defer below so that it runs after
	// it (defers run LIFO), which guarantees Defrob happens before Close.
	defer resource.Close()

	// Recover from any panic raised by Frob. If the panic is a FrobError, undo
	// the frob by calling Defrob with the error's defrobTag.
	defer func() {
		if r := recover(); r != nil {
			if fe, ok := r.(FrobError); ok {
				resource.Defrob(fe.defrobTag)
			}
			if e, ok := r.(error); ok {
				err = e
			} else {
				err = fmt.Errorf("panic: %v", r)
			}
		}
	}()

	resource.Frob(input)

	return nil
}
